from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from .models import ProcurementOrder

class ProcurementOrderTransitionView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request, order_id):
        target_status = request.data.get('target_status')
        # Validate that the order belongs to the user's organization and user is authorized
        try:
            order = ProcurementOrder.objects.get(pk=order_id, organization=request.user.organization)
        except ProcurementOrder.DoesNotExist:
            return Response({'error': 'Order not found'}, status=status.HTTP_404_NOT_FOUND)

        if not request.user.has_perm('procurement.can_approve_order'):
            return Response({'error': 'Lacking approval authority'}, status=status.HTTP_403_FORBIDDEN)

        if target_status not in ProcurementOrder.STATUS:
            return Response({'error': 'Invalid status transition'}, status=status.HTTP_400_BAD_REQUEST)

        order.status = target_status
        order.save(update_fields=['status'])
        return Response({'order_id': order.id, 'status': order.status})
